def _sections(spots):
    """[[region name, first n, last n], ...] in spot order."""
    out = []
    for s in spots:
        if out and out[-1][0] == s["dept"]: out[-1][2] = s["n"]
        else: out.append([s["dept"], s["n"], s["n"]])
    return out
SECTIONS = _sections(SPOTS)
